58	  constructor(private config: SidecarConfig) {}
59	
60	  /**
61	   * Core HTTP helper. Issues a fetch to the sidecar, attaches the auth header,
62	   * and deserialises the JSON response. Throws on any non-2xx status.
63	   */
64	  private async call<T>(path: string, method = "GET", body?: unknown): Promise<T> {
65	    const resp = await fetch(`${this.config.baseUrl}${path}`, {
66	      method,
67	      headers: {
68	        "Content-Type": "application/json",
69	        Authorization: `Bearer ${this.config.apiKey}`,
70	      },
71	      body: body ? JSON.stringify(body) : undefined,
72	    });
73	
74	    if (!resp.ok) {
75	      const text = await resp.text();
